// Generated by tools/base-cards.mjs; edit the base-cards JSON pack.
export const baseCardDefinitions = [{"id":"base.persistent-protection","name":"Ward Armor","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":2,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"base.persistent-block","stacks":4},{"op":"applyStatus","target":"self","status":"base.persistent-barrier","stacks":4}],"textTemplate":"Gain Persistent Block {base.persistent-block} and Persistent Barrier {base.persistent-barrier}.","icon":"skill","flavor":"Armor charm of the Bastion watch.\n\nThe ridge gates were held through long winters by guards too few to relieve one another. Their warding knots were tied into the lining, renewing a thin defense whenever the wearer could stand and breathe.\n\nThe cloth outlasted several suits of iron."},{"id":"base.greased","name":"Grease","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"enemy","status":"base.greased","stacks":3}],"textTemplate":"Apply Greased {base.greased}: fire detonates the coating.","icon":"skill","flavor":"Lamp oil prepared for the lower city's alleys.\n\nBefore the Burning, porters spread this heavy mixture beneath wheels to move stone uphill. The desperate later poured it across thresholds instead. Those who slipped could rise again, provided no one brought a torch.\n\nThe stair keeps both kinds of stain.","damageSchool":"fire"},{"id":"base.divine-strike","name":"Smite","class":"colorless","rarity":"uncommon","cost":2,"costRule":"fixed","staminaCost":2,"manaCost":1,"type":"attack","keywords":[],"effects":[{"op":"damage","target":"enemy","amount":{"f":"metric","metric":"weaponDamage","of":"self","per":3},"attack":{"source":"weapon"}},{"op":"damage","target":"enemy","amount":6,"tags":["school:divine"],"attack":{"source":"spell","damageType":"sacred"}}],"textTemplate":"Deal {damage} weapon damage and {damage.2} Sacred damage.","icon":"skill","flavor":"Consecrated stroke of the Citadel knights.\n\nA knight once carried the Court Flame's promise along the edge of a plain weapon. The oath was spoken before each watch, whether anyone remained to hear it or not. Some blades still answer the gesture.\n\nThe promise survived its intended keeper.","damageSchool":"physical","exposureBuildupPerHit":0},{"id":"base.poison","name":"Poison","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"enemy","status":"base.poison","stacks":5}],"textTemplate":"Apply {base.poison} Poison: 15 total Necrotic damage as it decays.","icon":"skill","flavor":"Bitter preparation of the weald's abandoned gardens.\n\nThe gardeners marked dangerous roots with white stakes so children could gather safely. When the Field Flame failed, the stakes were burned for warmth and the beds grew together. Their harvest now travels in stoppered bottles.\n\nNothing on the label promises a cure.","damageSchool":"magic"},{"id":"base.blight","name":"Blight","class":"colorless","contest":"mental","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"enemy","status":"base.blight","stacks":12}],"textTemplate":"Apply Blight {base.blight}: lethal when its stacks reach current HP.","icon":"skill","flavor":"A wasting drawn from the Field Flame's ruins.\n\nThe first dark patches were cut from the orchards and buried beyond the walls. Shoots rose from the burial ground the following spring. By winter, the fruit within the city bore the same marks beneath its skin.\n\nThe gardeners ran out of clean ground."},{"id":"base.weak","name":"Weaken","class":"colorless","contest":"physical","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"enemy","status":"base.weak","stacks":1}],"textTemplate":"Apply Weak {base.weak}.","icon":"skill","flavor":"A loosening charm once laid upon dangerous beasts.\n\nWardens used these small workings to bring wounded animals home without further harm. After the Burning, the same gestures were taught at the gate. It was easier to carry a prisoner who could no longer struggle.\n\nThe hand remembers its gentler purpose."},{"id":"base.charm","name":"Charm","class":"colorless","contest":"mental","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"enemy","status":"base.charm","stacks":1}],"textTemplate":"Apply Charm {base.charm}.","icon":"skill","flavor":"A courtly working carried beyond the frozen bridges.\n\nPetitioners learned to soften the attention of armed doorwardens before presenting their claims. The words lost their courtesy as the queues grew hungry. Their cadence still causes a raised weapon to hesitate before its appointed stroke.\n\nAn audience can be won without consent."},{"id":"base.bind","name":"Bind","class":"colorless","contest":"physical","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"enemy","status":"base.bind","stacks":1}],"textTemplate":"Apply Bind {base.bind}.","icon":"skill","flavor":"Restraint of the Bastion's old holding rooms.\n\nThe Wardens preferred a knot that checked the striking arm and left its bearer able to eat. Several survived on the empty cells after the keys were lost. Their pattern needs no rope when traced in ash.\n\nMercy had a shape before a name."},{"id":"base.restrained","name":"Restrain","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"enemy","status":"base.restrained","stacks":1},{"op":"addBurden","target":"enemy","card":"base.restrained-status-card","count":1,"pile":"hand"}],"textTemplate":"Apply Restrained {base.restrained}. Add a Restrained burden to the enemy hand.","icon":"skill","flavor":"A burdening seal of the Court's prisoners.\n\nThose brought over the bridges wore weighted cords beneath their sleeves. They could walk to judgment, but every movement reminded them of the escort. The cords rotted in the river vaults; the imposed weight remained in their knots.\n\nThe sentence travels lighter than its iron."},{"id":"base.foresight","name":"Foresight","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"base.foresight","stacks":3},{"op":"draw","amount":2}],"textTemplate":"Gain {base.foresight} Foresight and draw {draw} cards.","icon":"skill","flavor":"An exercise of the Observatory's night students.\n\nApprentices watched a candle's reflection through a bowl of dark water before they were allowed near the lenses. The practice taught them to notice a movement before seeking its cause. Few saw farther than the next breath.\n\nThat breath was sometimes sufficient."},{"id":"base.evade","name":"Evade","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"base.evade","stacks":1}],"textTemplate":"Gain Evade {base.evade}.","icon":"shield","flavor":"Footwork of the weald's narrow river crossings.\n\nBridge keepers taught travelers to turn sideways when a laden cart passed. During the fighting, the movement became a way to let steel pass just as closely. It requires little ground, and leaves little room for doubt.\n\nThe river took those who stepped twice."},{"id":"base.intangible","name":"Intangible","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":2,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"base.intangible","stacks":1}],"textTemplate":"Gain Intangible {base.intangible}.","icon":"skill","flavor":"A thinning learned among the Observatory's cold rooms.\n\nStudents were told to stand where the lens cast no image and listen for their own footsteps. Those who mastered the lesson could cross a door without stirring its hanging cloth. They returned colder than the stone.\n\nThe cloth never marked their passage."},{"id":"base.mirrors","name":"Mirrors","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":2,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"base.mirrors","stacks":1}],"textTemplate":"Gain Mirrors {base.mirrors}.","icon":"skill","flavor":"A fractured defense of the river city's salons.\n\nThe old houses hung polished plates beside their doors to multiply a guest's arrival. After the bridges froze, household magicians learned to give those reflections a brief weight. Intruders struck the nearest figure and heard glass break.\n\nThe remaining guest need not be real."},{"id":"base.elemental-weapon","name":"Elemental Weapon","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"base.elemental-weapon","stacks":2}],"textTemplate":"Enchant your weapon with Fire for {base.elemental-weapon} turns.","icon":"skill","flavor":"A furnace blessing carried on ordinary steel.\n\nThe Saints warmed the tools of workers assigned to the Observatory's outer stair. When the fuel carts stopped, a few tools retained their borrowed heat. Their owners discovered that the same blessing could be laid upon a blade.\n\nThe furnace asks no purpose of iron.","damageSchool":"fire"},{"id":"base.fire-cleanse","name":"Purifying Flame","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"damage","target":"self","amount":2,"tags":["school:fire"],"attack":{"source":"spell","damageType":"fire"}},{"op":"removeStatus","target":"self","status":"base.poison"},{"op":"removeStatus","target":"self","status":"base.greased"}],"textTemplate":"Take {damage} Fire damage. Remove Poison and Greased.","icon":"skill","flavor":"A harsh remedy of the Cinder Reach.\n\nMine workers burned spoiled dressings before returning beneath the ridge. In the last winters, the remedy was applied before the cloth was removed. Those who endured it escaped the creeping sickness, though none called the treatment gentle.\n\nClean flesh still bears the fire's account.","damageSchool":"fire","exposureBuildupPerHit":0},{"id":"base.divine-cleanse","name":"Divine Cleanse","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"removeStatus","target":"self","status":"base.weak"},{"op":"removeStatus","target":"self","status":"base.bind"},{"op":"removeStatus","target":"self","status":"base.restrained"}],"textTemplate":"Remove Weak, Bind and Restrained.","icon":"skill","flavor":"An unbinding rite of the Court Flame's attendants.\n\nThe attendants washed petitioners' hands before an oath could be heard. Later, they traced the washing gesture over fetters and old curses. The water was long gone, but the motion still persuaded certain bonds to loosen.\n\nA clean hand can carry an old wound.","damageSchool":"holy"},{"id":"base.necrotic-heal","name":"Necrotic Renewal","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"base.necrotic-healing","stacks":2}],"textTemplate":"Convert incoming Necrotic damage to healing for {base.necrotic-healing} turns.","icon":"skill","flavor":"A forbidden recovery of the Furnace Chapel.\n\nThe sick were once kept apart from the Chapel's warm stones. A few learned to draw sustenance from the very cold that gathered around their beds. They survived to leave the rooms, carrying no warmth that others could share.\n\nThe cure did not restore their welcome.","damageSchool":"magic"},{"id":"base.divine-harm","name":"Profane Inversion","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"enemy","status":"base.divine-harm","stacks":2}],"textTemplate":"Convert the enemy’s Sacred healing into damage for {base.divine-harm} turns.","icon":"skill","flavor":"An inversion found beneath the river city's shrines.\n\nThe shrines offered comfort to those whom the Court would not hear. After the Burning, their bowls filled with black water and the comforting words turned bitter. A practiced hand can direct that bitterness toward another's blessing.\n\nThe prayer arrives with its meaning reversed.","damageSchool":"holy"},{"id":"base.shuffle-hand","name":"Hand Shuffle","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"moveCards","amount":3,"from":"hand","to":"draw","selection":"random","position":"random"},{"op":"draw","amount":3}],"textTemplate":"Shuffle up to {draw} random hand cards into draw. Draw 3.","icon":"shield","flavor":"A road lesson taught with a traveler's worn cards.\n\nCaravan guards changed their watches whenever the same sequence grew familiar. A dangerous habit could be broken by putting every expected duty aside and taking another. The method survived on roads where there were no caravans left.\n\nFamiliarity is a route an enemy learns."},{"id":"base.shuffle-deck","name":"Deck Shuffle","class":"colorless","rarity":"common","cost":0,"costRule":"fixed","staminaCost":0,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"moveCards","amount":100,"from":"draw","to":"draw","selection":"random","position":"random"}],"textTemplate":"Shuffle up to 100 random cards in your draw pile.","icon":"shield","flavor":"An ordering exercise of the Observatory's apprentices.\n\nThe students sorted loose charts until each could name their place by touch. Their teachers then scattered the stack and ordered them to begin again. The exercise continued after the charts ceased to describe the sky outside.\n\nNo arrangement was permitted to become certain."},{"id":"base.draw","name":"Draw","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"draw","amount":2}],"textTemplate":"Draw {draw} cards.","icon":"shield","flavor":"A preparation shared by the ring road's survivors.\n\nTravelers kept a useful thing within reach and another beneath it, wrapped against the wet. Those who returned from the towers made the same small preparations before sleeping. A ready hand mattered more than a crowded pack.\n\nThe next necessity rarely announces itself."},{"id":"base.retain","name":"Retain","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"modifyCards","amount":2,"from":"hand","selection":"choose","changes":{"retain":true}}],"textTemplate":"Choose up to 2 hand cards to retain.","icon":"shield","flavor":"A keeper's habit from the Bastion granaries.\n\nWhen the harvest was sound, each storekeeper set aside a measure that could not be touched at market. The custom remained after the stores were emptied. Fighters learned to reserve a useful movement with the same stubborn care.\n\nHunger is not the only thing to anticipate."},{"id":"base.scout","name":"Scout","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"moveCards","amount":3,"from":"draw","to":"draw","selection":"choose","position":"top","look":3}],"textTemplate":"Look at the top 3 cards. Choose their order.","icon":"shield","flavor":"A pathfinder's method on the old viaducts.\n\nThe first travelers after the Burning tested each arch with a weighted cord before bringing the others forward. They marked the sound stones in an order the wind could not erase. Later parties sometimes found the marks rearranged.\n\nA known road must still be examined."},{"id":"base.reveal-opponent-hand","name":"Read Intent","class":"colorless","contest":"mental","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"base.read-intent","stacks":1},{"op":"revealIntent","target":"enemy","amount":1}],"textTemplate":"Gain {base.read-intent}. Reveal the selected enemy's intent and burden hand for 1 turn.","icon":"skill","flavor":"A watcher's discipline of the Citadel bridges.\n\nDoorwardens learned to read a visitor's hands before accepting any spoken purpose. The habit became more exact when the river froze and armed supplicants arrived together. A pause at the wrist could reveal more than a drawn blade.\n\nIntent leaves a mark before iron moves."},{"id":"base.recall-choose","name":"Recall","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"moveCards","amount":1,"from":"discard","to":"hand","selection":"choose","position":"top"}],"textTemplate":"Choose a discarded card to return to hand.","icon":"shield","flavor":"A recovery drill of the Bastion's shield yard.\n\nNovices were made to repeat a failed movement after every other student had taken a turn. The delay stripped away haste and left the motion clear. Veterans carried the drill into fights that offered no patient teacher.\n\nWhat was abandoned need not be lost."},{"id":"base.recover-exile","name":"Exile Recovery","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"moveCards","amount":1,"from":"exhaust","to":"hand","selection":"choose","position":"top"}],"textTemplate":"Choose an exhausted card to return to hand.","icon":"shield","flavor":"An old retrieval practiced at the Observatory's refuse stair.\n\nBroken instruments were cast into a pit beneath the workshops. Poor apprentices climbed down for pieces the masters considered spent. Sometimes a discarded lens revealed a star the great glass had missed for an entire season.\n\nThe refuse retained its own small light."},{"id":"base.exhaust-choose","name":"Chosen Exhaust","class":"colorless","rarity":"common","cost":0,"costRule":"fixed","staminaCost":0,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"moveCards","amount":1,"from":"hand","to":"exhaust","selection":"choose","position":"top"}],"textTemplate":"Choose a hand card to exhaust.","icon":"shield","flavor":"A deliberate sacrifice of the road's traveling schools.\n\nA climber cannot carry every lesson into every chamber. Teachers made their pupils lay one practiced movement aside before opening a difficult door. The empty place left room for attention, though the surrendered habit sometimes proved hard to recover.\n\nReadiness has always required a leaving behind."},{"id":"base.transform","name":"Transform","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"moveCards","amount":1,"from":"hand","to":"hand","selection":"choose","position":"top","transformTo":"base.strike"}],"textTemplate":"Transform a chosen hand card into Strike for this combat.","icon":"skill","flavor":"A simplifying art of the Bastion's oldest instructors.\n\nThe instructors stripped elaborate exercises back to the first straight blow whenever a pupil grew confused. Finer details could be learned again after the hands stopped trembling. In the towers, that patient correction became a swift and necessary spell.\n\nA beginning can still serve an ending."},{"id":"base.status-card-stagger","name":"Staggering Burden","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"addBurden","target":"enemy","card":"base.stagger-status-card","count":2}],"textTemplate":"Add 2 Stagger burdens to the enemy deck.","icon":"skill","flavor":"A stumbling curse carried in the Court's broken bells.\n\nThe bridge bells once kept the procession moving at a measured pace. When their towers fell, the sound arrived in uneven fragments. Those who caught its rhythm faltered in midstride, as though the next stone had been taken away.\n\nThe missing beat leaves a place for steel."},{"id":"base.status-card-paralyze","name":"Paralyzing Burden","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"addBurden","target":"enemy","card":"base.paralysis-status-card","count":2}],"textTemplate":"Add 2 Paralysis burdens to the enemy deck.","icon":"skill","flavor":"A locking curse of the river city's empty cells.\n\nThe gaolers kept certain prisoners still without tightening their chains. Its pattern was scratched into the doorframes for a replacement watch to learn. The cells are open now, but the old instruction can still seize a living limb.\n\nAn open door does not release everything."},{"id":"base.exhaust","name":"Exhaust","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":["exhaust"],"effects":[{"op":"heal","target":"self","amount":8}],"textTemplate":"Heal {heal} HP. Exhaust.","icon":"shield","flavor":"A final reserve of the road's exhausted climbers.\n\nThose who reached a landing wounded sometimes bound their last clean cloth around their chest and stood. There would be no second dressing at the next stair. The resolve of that moment became a working taught without ceremony.\n\nThe cloth is spent before the climb is."},{"id":"base.ethereal","name":"Ethereal","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":["ethereal"],"effects":[{"op":"block","target":"self","amount":10}],"textTemplate":"Gain {block} Block. Ethereal.","icon":"shield","flavor":"A brief shelter drawn from the Observatory's fading glass.\n\nThe outer windows once softened the heat that gathered beneath the great lens. Shards carried away after the Burning could still hold a pale screen for an instant. In an unwatched hand, they crumbled before the next breath.\n\nThe shelter lasts only while it is needed."},{"id":"base.stat-buff","name":"Empower","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"strength","stacks":2}],"textTemplate":"Gain {strength} Strength for this combat.","icon":"shield","flavor":"A strengthening rite of the Bastion's stone carriers.\n\nLaborers pressed both palms against the first block before beginning the morning's lift. The gesture steadied tired arms through a day on the ridge. Their descendants found the same borrowed resolve useful beneath a weapon's weight.\n\nStone taught the hand before steel did."},{"id":"base.drain-allies","name":"Shared Sacrifice","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"loseHp","target":"allAllies","amount":3},{"op":"block","target":"self","amount":12}],"textTemplate":"All allies lose {loseHp} HP. Gain {block} Block.","icon":"shield","flavor":"A shared defense of the ring road's last escorts.\n\nAn escort sometimes closed ranks around the weakest traveler and bore the blows together. A harsher working drew the price from every companion before any enemy struck. The traveler it saved was left to remember each willing face.\n\nShelter can leave wounds on either side."},{"id":"base.scale-negative-status","name":"Affliction Scaling","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"attack","keywords":[],"effects":[{"op":"damage","target":"enemy","amount":{"f":"add","args":[6,{"f":"metric","metric":"negativeStatusTypes","of":"target","statuses":["weak","vulnerable","burn","venom","base.weak","base.charm","base.bind","base.restrained","base.poison","base.blight","base.greased"],"per":2}]}}],"textTemplate":"Deal {damage} damage, scaling with distinct negative statuses.","icon":"attack","flavor":"A cruel calculation of the river city's interrogators.\n\nThe interrogators kept separate marks for cold, hunger, and the smaller pains inflicted between questions. Each new mark narrowed a prisoner's remaining resistance. Their successors learned to strike where several afflictions had already begun their work.\n\nThe ledger counted injuries as opportunities.","damageSchool":"physical","exposureBuildupPerHit":0},{"id":"base.scale-damage-taken","name":"Reprisal Growth","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"attack","keywords":[],"effects":[{"op":"damage","target":"enemy","amount":{"f":"add","args":[6,{"f":"metric","metric":"damageTakenThisTurn","of":"self","per":0.5}]}}],"textTemplate":"Deal {damage} damage, scaling with HP lost this turn.","icon":"attack","flavor":"A reprisal taught among the Bastion's battered gate guards.\n\nRelief seldom came before the second assault. The guards learned to turn the force that drove them backward into the next blow forward. Those who survived could tell the cost of a watch by its last strike.\n\nThe gate remembered every attempt to break it.","damageSchool":"physical","exposureBuildupPerHit":0},{"id":"base.growth-per-type","name":"Discipline Growth","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"block","target":"self","amount":{"f":"add","args":[4,{"f":"metric","metric":"distinctTypes","of":"self","per":2}]}}],"textTemplate":"Gain {block} Block, scaling with distinct types played this turn.","icon":"shield","flavor":"A defense assembled from the ring road's scattered schools.\n\nThe towers once demanded separate loyalties from their fighters. On the roads between them, survivors exchanged the movements that had kept them alive. A guard became stronger when it could answer more than one kind of danger.\n\nNo ruined school could afford its old pride."},{"id":"base.cost-per-use","name":"Shifting Cost","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"attack","keywords":[],"effects":[{"op":"damage","target":"enemy","amount":8}],"textTemplate":"Deal {damage} damage. Costs +1 SP per prior play this combat (maximum +3).","icon":"attack","flavor":"An exacting stroke of the Citadel's formal duels.\n\nA duelist was expected to end the matter before fatigue spoiled the prescribed line. Those forced to repeat it found the weapon heavier on each return. The body paid for an elegance that the watching Court rarely questioned.\n\nA perfect motion does not become easier.","damageSchool":"physical","exposureBuildupPerHit":0,"costGrowth":{"stamina":1,"mana":0,"perUse":1,"max":3}},{"id":"base.damage-per-use","name":"Rising Damage","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"attack","keywords":[],"effects":[{"op":"damage","target":"enemy","amount":{"f":"add","args":[6,{"f":"metric","metric":"sameCardPlays","of":"self","per":3}]}}],"textTemplate":"Deal {damage} damage, increasing each time this card is played.","icon":"attack","flavor":"A relentless exercise of the Bastion's quarry fighters.\n\nStone breakers struck along one line until the hidden fault yielded. Their children brought the practice into the shield yard, refusing to change a stroke that had not yet found its depth. Each return carried the weight of the last.\n\nThe fracture arrives before the stone admits it.","damageSchool":"physical","exposureBuildupPerHit":0},{"id":"base.pay-x-effect","name":"Channel X","class":"colorless","rarity":"uncommon","cost":"X","costRule":"fixed","staminaCost":0,"manaCost":1,"type":"attack","keywords":[],"effects":[{"op":"damage","target":"enemy","amount":{"f":"energySpent","per":6}}],"textTemplate":"Spend all remaining SP. Deal {damage} damage.","icon":"skill","flavor":"An undivided exertion of the road's solitary climbers.\n\nA locked stair offers no promise of another attempt. Some climbers learned to gather every remaining measure of effort into one committed motion. What followed depended on whether the obstruction or the climber gave way first.\n\nNothing was kept for the next landing.","damageSchool":"physical","exposureBuildupPerHit":0},{"id":"base.pay-x-targets","name":"Spread X","class":"colorless","rarity":"uncommon","cost":"X","costRule":"fixed","staminaCost":0,"manaCost":1,"type":"attack","keywords":[],"effects":[{"op":"damage","target":"allEnemies","amount":8}],"textTemplate":"Spend all remaining SP. Deal {damage} damage to up to X enemies.","icon":"skill","flavor":"A widening assault of the Bastion's crowded breach drills.\n\nThe instructors packed the yard with wooden figures when recruits grew too certain of a single opponent. A fighter learned to carry one movement across as many openings as their strength allowed. The yard left no place to rest.\n\nA breach seldom admits only one enemy.","damageSchool":"physical","exposureBuildupPerHit":0,"targetLimit":{"f":"energySpent","per":1}},{"id":"base.hide-cards","name":"Conceal","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"base.conceal","stacks":2},{"op":"modifyCards","from":"hand","amount":{"f":"stacks","status":"base.conceal","of":"self"},"selection":"choose","changes":{"hideTurns":{"f":"stacks","status":"base.conceal","of":"self"}}}],"textTemplate":"Gain {base.conceal} Conceal. Hide X hand cards for X turns, where X is your Conceal stacks.","icon":"skill","flavor":"A concealment practiced by the river city's couriers.\n\nMessages were sewn inside an empty fold rather than beneath a conspicuous seal. Some couriers learned to put the fold itself beyond a searcher's touch. What they hid returned later, sometimes after its appointed recipient was gone.\n\nAn absent thing can still keep its appointment."},{"id":"base.force-stance","name":"Force Stance","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"enterStance","target":"enemy","maneuver":"defend"}],"textTemplate":"Force the enemy into Defend.","icon":"skill","flavor":"A coercive feint of the Citadel's shield masters.\n\nThe masters taught a threatening step that made an opponent cover before choosing to do so. In practice the wooden blade stopped short. Beyond the yard, the same step could close a fighter inside a defense they had not intended.\n\nA guard can become its own confinement."},{"id":"base.multi-stance","name":"Many Forms","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"base.many-forms","stacks":1}],"textTemplate":"Gain {base.many-forms} Many Forms: hold up to 2 stances until next turn.","icon":"shield","flavor":"A divided discipline of the road's wandering instructors.\n\nNo tower trained a pupil to hold two answers at once. The travelers who taught between the seats had fewer certainties and more scars. They learned to keep one motion ready while the body seemed committed to another.\n\nThe road required room for a second lesson."},{"id":"base.current-stance-variant","name":"Stance Echo","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"attack","keywords":[],"effects":[{"op":"damage","target":"enemy","amount":6}],"textTemplate":"Smash: deal 12 damage. Otherwise gain {damage} Block.","icon":"attack","flavor":"An answering form of the Bastion's shield yard.\n\nThe same turn of the shoulder served different purposes under different weights. With a raised weapon it drove forward; behind a settled guard it closed the opening. Instructors judged the footing before they corrected the hands.\n\nThe body gives a motion its meaning.","damageSchool":"physical","exposureBuildupPerHit":0,"effectVariants":[{"if":{"p":"inStance","stance":"smash"},"effects":[{"op":"damage","target":"enemy","amount":12}],"textTemplate":"Deal {damage} damage."},{"if":{"p":"all","preds":[]},"effects":[{"op":"block","target":"self","amount":6}],"textTemplate":"Gain {block} Block."}]},{"id":"base.paid-resource-variant","name":"Resource Echo","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"attack","keywords":[],"effects":[{"op":"damage","target":"enemy","amount":12}],"textTemplate":"If MP was paid, deal {damage} damage; otherwise gain 8 Block.","icon":"skill","flavor":"A borrowed cadence of the Observatory's armed attendants.\n\nSome attendants could kindle a spell along the motion of a blade. Others repeated the same motion without its light and found it settled into a serviceable guard. Both remained in the drills after the teachers stopped distinguishing them.\n\nThe hand remembers whether it carried fire.","damageSchool":"physical","exposureBuildupPerHit":0,"effectVariants":[{"if":{"p":"resourcePaid","resource":"mana","amount":1},"effects":[{"op":"damage","target":"enemy","amount":12}],"textTemplate":"Deal {damage} damage."},{"if":{"p":"all","preds":[]},"effects":[{"op":"block","target":"self","amount":8}],"textTemplate":"Gain {block} Block."}]},{"id":"base.attack-then-defend","name":"Strike and Settle","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"attack","keywords":[],"effects":[{"op":"damage","target":"enemy","amount":8},{"op":"enterStance","choose":"maneuver"}],"textTemplate":"Deal {damage} damage, then choose a maneuver stance.","icon":"attack","flavor":"A returning stroke of the Bastion's gate watches.\n\nThe first instruction was never to leave the weapon where the blow ended. Guards practiced finding a new footing while the edge was still returning. Those who forgot were corrected by a wooden staff across the unprotected ribs.\n\nA strike ends only when its bearer is ready.","damageSchool":"physical","exposureBuildupPerHit":0},{"id":"base.modify-card-stance","name":"Reframe","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"modifyCards","amount":1,"from":"hand","selection":"choose","changes":{"maneuver":"smash"}}],"textTemplate":"Choose a hand card. Change its maneuver to Smash this combat.","icon":"shield","flavor":"A forceful correction of the Citadel's dueling schools.\n\nInstructors sometimes placed a heavier practice blade into a pupil's hands without warning. A familiar technique then required a different commitment of shoulder and hip. The lesson was carried into battle by fighters who could no longer choose their tools.\n\nThe old motion accepted a different weight."},{"id":"base.modify-card-range","name":"Extend","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"modifyCards","amount":1,"from":"hand","selection":"choose","changes":{"range":"reach"}}],"textTemplate":"Choose a hand card. Change its range to Reach this combat.","icon":"shield","flavor":"An extending art of the weald's polearm keepers.\n\nThe keepers borrowed the motions of shorter weapons when the bridge left no room for a proper swing. A loosened grip and a careful step gave the remembered stroke another span. Its origin remained visible only to a patient teacher.\n\nDistance changes the reach of an old lesson."},{"id":"base.extra-weapon","name":"Extra Weapon","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"base.extra-weapon","stacks":1}],"textTemplate":"Gain {base.extra-weapon} extra weapon action this turn.","icon":"shield","flavor":"A second opening of the Bastion's veteran guards.\n\nThe newest recruits counted attacks as separate exertions. Veterans learned to keep the weapon moving while the first opponent still recoiled, finding another opening before the line closed. The extra stroke depended on preparation made before either enemy moved.\n\nThe interval belonged to the ready hand."},{"id":"base.extra-shield","name":"Extra Shield","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"base.extra-shield","stacks":1}],"textTemplate":"Gain {base.extra-shield} extra shield action this turn.","icon":"shield","flavor":"A returning defense of the Citadel's bridge watches.\n\nTwo guards once shared each narrow post, turning their shields in a practiced sequence. After the watches thinned, a survivor had to answer both parts alone. Their descendants learned the second turn without ever seeing the partner it replaced.\n\nThe empty post still has its appointed movement."},{"id":"base.auto-counter","name":"Automatic Counter","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"base.auto-counter","stacks":1}],"textTemplate":"Prepare one automatic counterattack. base.auto-counter: {base.auto-counter}.","icon":"shield","flavor":"A waiting answer of the Bastion's shield masters.\n\nPupils stood behind a raised board while the instructor struck it without a count. They were forbidden to pursue the staff and taught instead to answer its contact. Years later, some could begin the reply before knowing they had been attacked.\n\nThe lesson waited in the arm."},{"id":"base.auto-sweep","name":"Automatic Sweep","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"base.auto-sweep","stacks":1}],"textTemplate":"Prepare one automatic sweep. base.auto-sweep: {base.auto-sweep}.","icon":"shield","flavor":"A prepared circle of the ring road's caravan guards.\n\nAn escort surrounded by thieves could not watch every approach. Guards planted their feet and learned to turn at the first touch of a blade. The motion cleared space for the travelers, even when its bearer never saw the attacker.\n\nThe road was measured by the weapon's return."},{"id":"base.reflect","name":"Reflect","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"base.reflect","stacks":1}],"textTemplate":"Reflect eligible incoming damage for {base.reflect} turn.","icon":"skill","flavor":"A returning ward of the Observatory's polished chambers.\n\nThe lens workers fitted their masks with silvered plates against sudden flares. A few plates sent more than light back toward its origin. The attendants preserved the pattern after the workshops emptied, though the reflected pain had no brightness.\n\nWhat strikes the surface finds its way home."},{"id":"base.guard-allies","name":"Interpose","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"base.guard-allies","stacks":1},{"op":"block","target":"self","amount":8}],"textTemplate":"Gain {block} Block and guard allies for {base.guard-allies} turn.","icon":"shield","flavor":"A sheltering oath of the Bastion's road wardens.\n\nThe Wardens walked between the wagons and the tree line, keeping their shields toward the unseen ground. An escort was judged by who arrived behind them, rather than by wounds received. The oath endured after the wagons stopped coming.\n\nAn empty road can still be guarded."},{"id":"base.transmute","name":"Transmute","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"moveCards","amount":1,"from":"hand","to":"exhaust","selection":"choose","position":"top"},{"op":"addCinders","amount":10}],"textTemplate":"Exhaust a chosen hand card. Gain {addCinders} cinders.","icon":"shield","flavor":"A frugal working of the Cinder Reach's traveling smiths.\n\nBroken tools were weighed before they entered the furnace, and nothing useful was thrown away whole. Some smiths learned to draw cinders from a spent working with the same care. The recovered warmth bought another small necessity along the road.\n\nWhat is surrendered leaves something in the palm."},{"id":"base.one-use-scroll","name":"Spell Scroll","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":["exhaust"],"effects":[{"op":"castLinkedSpell","card":"base.foresight"}],"textTemplate":"Cast Foresight. One play per combat; exhaust this scroll.","icon":"skill","flavor":"A foresight exercise copied by an Observatory apprentice.\n\nThe student traced each curve slowly enough to remember the next before the ink dried. A traveler could later borrow that moment of clarity by opening the sheet. Its careful lines blackened as soon as they were read.\n\nThe lesson survived for one more pupil.","playLimit":1},{"id":"base.gain-resource","name":"Resource Gain","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"restoreStamina","target":"self","amount":3}],"textTemplate":"Restore {restoreStamina} SP.","icon":"skill","flavor":"A measured recovery of the weald's ridge workers.\n\nWorkers rested at marked stones on the climb to the Bastion, setting their loads down before their knees failed. The short interval was counted in steady breaths. Fighters learned to find the same recovery without leaving their place in the line.\n\nRest need not wait for a safe road."},{"id":"base.buff-ally","name":"Ally Empowerment","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"ally","status":"strength","stacks":2}],"textTemplate":"Give an ally {strength} Strength for this combat.","icon":"shield","flavor":"An encouragement kept by the Bastion's shared watches.\n\nThe guards touched a companion's shoulder before exchanging places at the gate. A small working grew around the gesture, lending tired arms some of the giver's resolve. It passed between survivors long after the gate ceased to stand.\n\nThe hand is withdrawn; the steadiness remains."},{"id":"base.break-ward","name":"Ward Break","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"wardDamage","target":"enemy","amount":8}],"textTemplate":"Deal 8 Ward damage.","wardOffTextTemplate":"Deal {poiseDamage} Poise damage.","icon":"skill","flavor":"A disrupting touch of the Observatory's instrument keepers.\n\nThe keepers tested old seals before moving a lens from its housing. A precise disturbance could loosen a ward without shattering the glass beneath it. The method later found use against defenses made to protect less delicate things.\n\nThe opening is smaller than the harm it permits."},{"id":"base.break-poise","name":"Poise Break","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"poiseDamage","target":"enemy","amount":8}],"textTemplate":"Deal {poiseDamage} Poise damage.","icon":"shield","flavor":"A staggering blow of the Bastion's quarry crews.\n\nQuarry workers drove wedges where the weight of a block already strained its bed. A short stroke could unsettle stone too large to break outright. Their fighting descendants sought the same yielding place beneath armor and planted feet.\n\nWhat cannot be broken can still be moved."},{"id":"base.generate-smash","name":"Smash Creation","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"addCard","card":"base.smash","pile":"hand","count":1}],"textTemplate":"Add a temporary Smash to hand.","icon":"shield","flavor":"A recalled stroke of the Citadel's heavy weapon drills.\n\nA recruit carried a wooden mallet before being trusted with the armory's iron. Instructors made its simple downward path the last exercise of every watch. Even an empty hand could remember the weight when no suitable weapon remained.\n\nThe practiced burden waits for another shape."},{"id":"base.conditional-damage-bonus","name":"Conditional Strike","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"attack","keywords":[],"effects":[{"op":"damage","target":"enemy","amount":6},{"op":"damage","target":"enemy","amount":6,"if":{"p":"inStance","stance":"smash"}}],"textTemplate":"Deal {damage} damage. In Smash stance, deal {damage.2} more.","icon":"attack","flavor":"A committed strike of the Bastion's breach fighters.\n\nThe guards held their heavier blows until their footing could carry the whole body forward. Striking from an unsettled guard wasted the opening and often the weapon. The old drill made patience part of an apparently reckless motion.\n\nThe strength was waiting beneath the stance.","damageSchool":"physical","exposureBuildupPerHit":0},{"id":"base.perception-untargetable","name":"Veil","class":"colorless","rarity":"uncommon","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":1,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"base.veil","stacks":2}],"textTemplate":"Gain Veil for {base.veil} turns. Single-target actions require a Perception check; area actions bypass it.","icon":"skill","flavor":"A veiling art of the river city's hidden messengers.\n\nCouriers crossed occupied bridges by moving where a watcher's attention had just departed. A small working deepened that omission until a searching gaze passed over them. Those with a practiced eye could still find the disturbance in the crowd.\n\nA missing figure leaves an occupied space."},{"id":"base.retain-block","name":"Hold Block","class":"colorless","rarity":"common","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"applyStatus","target":"self","status":"base.retain-block","stacks":1},{"op":"block","target":"self","amount":6}],"textTemplate":"Gain {block} Block. Retain Block for {base.retain-block} turn.","icon":"shield","flavor":"A settled guard of the Citadel's long watches.\n\nThe bridge guards learned to hold their shields through the quiet between assaults without letting the shoulders slacken. Their stance preserved work already done instead of demanding it anew. The practice remained useful when the bridges became a frozen road.\n\nThe pause does not belong to the attacker."},{"id":"base.immediate-stance-transition","name":"Flowing Transition","class":"colorless","rarity":"common","cost":0,"costRule":"fixed","staminaCost":0,"manaCost":0,"type":"skill","keywords":[],"effects":[{"op":"enterStance","choose":"maneuver"}],"textTemplate":"Immediately choose a maneuver stance.","icon":"shield","flavor":"A passing form of the road's traveling duelists.\n\nA lesson borrowed in one city rarely answered every danger in the next. Travelers practiced changing their footing between breaths rather than between engagements. Those who managed it could leave an old commitment before an enemy found its opening.\n\nThe road did not wait for a formal beginning."},{"id":"base.stagger-status-card","name":"Stagger","class":"colorless","rarity":"special","cost":0,"costRule":"fixed","staminaCost":0,"manaCost":0,"type":"status","keywords":["ethereal","unplayable"],"effects":[],"textTemplate":"Skip your next action when drawn. Ethereal.","icon":"shield","flavor":"An interruption carried by a broken bell's cadence.\n\nThe body seeks the missing beat and finds no footing. By the time its balance returns, the opening has already passed.\n\nThe next step belongs to someone else.","burden":{"skipActions":1,"staminaTax":0,"manaTax":0,"status":"base.stagger"}},{"id":"base.multi-hit","name":"Multiple Strikes","class":"colorless","rarity":"common","cost":2,"costRule":"fixed","staminaCost":2,"manaCost":0,"type":"attack","keywords":[],"effects":[{"op":"damage","target":"enemy","amount":4,"hits":3},{"op":"wardDamage","target":"enemy","amount":3},{"op":"poiseDamage","target":"enemy","amount":3}],"textTemplate":"Strike {hits} times for {damage} damage. Deal {poiseDamage} Ward and 3 Poise damage total.","wardOffTextTemplate":"Strike {hits} times for {damage} damage. Deal {poiseDamage} Poise damage total.","icon":"attack","flavor":"A repeated stroke of the weald's short-blade escorts.\n\nIn a crowded passage, there was no room to draw back for a great blow. Escorts learned to strike along the returning path, turning small openings into a succession of wounds. The enemy's guard had to answer every movement separately.\n\nA narrow space need not mean a single chance.","damageSchool":"physical","exposureBuildupPerHit":0},{"id":"base.paralysis-status-card","name":"Paralysis","class":"colorless","rarity":"special","cost":0,"costRule":"fixed","staminaCost":0,"manaCost":0,"type":"status","keywords":["ethereal","unplayable"],"effects":[],"textTemplate":"Skip your next action when drawn. Ethereal.","icon":"shield","flavor":"A lingering command of the river city's gaolers.\n\nThe fingers close without taking hold of anything. The old restraint needs neither a chain nor a prisoner who remembers the charge.\n\nRelease comes after the moment it was needed.","burden":{"skipActions":1,"staminaTax":0,"manaTax":0,"status":"base.paralysis"}},{"id":"base.restrained-status-card","name":"Restrained","class":"colorless","rarity":"special","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"status","keywords":["ethereal","unplayable"],"effects":[],"textTemplate":"Your actions cost +1 SP while this burden is held. Ethereal.","icon":"shield","flavor":"A remembered weight from the Court's holding rooms.\n\nThe cord is gone, but each movement still pays its toll. Prisoners learned to make fewer gestures while waiting for a door to open.\n\nThe burden has outlived its fastening.","burden":{"skipActions":0,"staminaTax":1,"manaTax":0,"ranges":["melee","reach"],"cardTypes":["attack"],"status":"base.restrained-burden"}},{"id":"base.strike","name":"Strike","class":"colorless","rarity":"special","cost":1,"costRule":"fixed","staminaCost":1,"manaCost":0,"type":"attack","keywords":[],"effects":[{"op":"damage","target":"enemy","amount":6}],"textTemplate":"Deal {damage} damage.","icon":"attack","damageSchool":"physical","exposureBuildupPerHit":0,"flavor":"A plain stroke shared by the ring road's survivors.\n\nEach tower claimed a finer school, and each school began by teaching the hand to carry an edge straight toward its mark. Travelers kept that first lesson when the schools and their quarrels were left behind.\n\nThe simplest instruction still has work to do."},{"id":"base.smash","name":"Smash","class":"colorless","rarity":"special","cost":2,"costRule":"fixed","staminaCost":2,"manaCost":0,"type":"attack","keywords":[],"effects":[{"op":"damage","target":"enemy","amount":12}],"textTemplate":"Deal {damage} damage.","icon":"attack","damageSchool":"physical","exposureBuildupPerHit":0,"flavor":"A heavy stroke remembered from the Bastion's stone yards.\n\nA block that resisted the first careful blow sometimes needed the whole weight of the worker behind the next. The motion passed from mallet to weapon without losing its patient preparation or its unkind finish.\n\nThe arm follows where the body has committed."}];
